using System.Collections;
using System.Collections.Generic;
using FMOD.Studio;
using FMODUnity;
using NaughtyAttributes;
using UnityEngine;

public class SFXHandler : ReferenceSingleton<SFXHandler>
{
	[SerializeField]
	private EventReference uiDiceRoll;

	[Header("Debug")]
	[SerializeField]
	private EventReference debugSFX;

	public EventInstance debugEventInstance;

	[SerializeField]
	private int debugSFXAmount = 1;

	[SerializeField]
	private List<EventReference> debugSFXAtTheSameTime;

	private Bus sfxBus;

	public EventInstance PlayerReceivingCorruptionEventInstance;

	private List<EventReference> eventReferencesWaitingForDelay = new List<EventReference>();

	private List<EventReference> eventReferencesWaitingForDelaySecond = new List<EventReference>();

	[Button(null)]
	public void PlayDebugSFX()
	{
		for (int i = 0; i < debugSFXAmount; i++)
		{
			RuntimeManager.PlayOneShot(debugSFX);
		}
	}

	[Button(null)]
	public void PlayDebugSFXEventReferencesWaitingForDelay()
	{
		for (int i = 0; i < debugSFXAmount; i++)
		{
			PlaySFX(debugSFX);
		}
	}

	[Button(null)]
	public void PlayOnInstanceOnlyDebugSFX()
	{
		for (int i = 0; i < debugSFXAmount; i++)
		{
			PlayOneInstanceOnlySFX(ref debugEventInstance, debugSFX);
		}
	}

	[Button(null)]
	public void PlayAllDebugsAtTheSameTimeSFX()
	{
		for (int i = 0; i < debugSFXAtTheSameTime.Count; i++)
		{
			RuntimeManager.PlayOneShot(debugSFXAtTheSameTime[i]);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		sfxBus = RuntimeManager.GetBus("bus:/SFX");
	}

	public void PlaySFX(EventReference eventReference)
	{
		if (!eventReferencesWaitingForDelay.Contains(eventReference) || !eventReferencesWaitingForDelaySecond.Contains(eventReference))
		{
			if (!eventReferencesWaitingForDelay.Contains(eventReference))
			{
				eventReferencesWaitingForDelay.Add(eventReference);
				StartCoroutine(EventReferencesWaitingForDelayCoroutine(eventReference));
			}
			else if (!eventReferencesWaitingForDelaySecond.Contains(eventReference))
			{
				eventReferencesWaitingForDelaySecond.Add(eventReference);
			}
			RuntimeManager.PlayOneShot(eventReference);
		}
	}

	private IEnumerator EventReferencesWaitingForDelayCoroutine(EventReference eventReference)
	{
		yield return new WaitForSeconds(0.005f);
		eventReferencesWaitingForDelay.Remove(eventReference);
		eventReferencesWaitingForDelaySecond.Remove(eventReference);
	}

	public void PlaySFXWithEventInstanceReference(ref EventInstance eventInstance, EventReference eventReference)
	{
		eventInstance = RuntimeManager.CreateInstance(eventReference);
		eventInstance.start();
		eventInstance.release();
	}

	public void PlayLoopableSFX(ref EventInstance eventInstance, EventReference eventReference)
	{
		if (!IsSFXPlaying(ref eventInstance))
		{
			PlaySFXWithEventInstanceReference(ref eventInstance, eventReference);
		}
	}

	public void PlayOneInstanceOnlySFX(ref EventInstance eventInstance, EventReference eventReference)
	{
		if (IsSFXPlaying(ref eventInstance))
		{
			StopSFX(ref eventInstance);
		}
		PlaySFXWithEventInstanceReference(ref eventInstance, eventReference);
	}

	public bool IsSFXPlaying(ref EventInstance eventInstance)
	{
		eventInstance.getPlaybackState(out var state);
		return state == PLAYBACK_STATE.PLAYING;
	}

	public void StopSFX(ref EventInstance eventInstance)
	{
		eventInstance.stop(FMOD.Studio.STOP_MODE.ALLOWFADEOUT);
	}

	public void StopAllSFX()
	{
		sfxBus.stopAllEvents(FMOD.Studio.STOP_MODE.IMMEDIATE);
	}

	public bool IsPlayerReceivingCorruptionSFXPlaying()
	{
		return IsSFXPlaying(ref PlayerReceivingCorruptionEventInstance);
	}

	public void SetSFXBusPaused(bool value)
	{
		sfxBus.setPaused(value);
	}

	public void OnRollDices()
	{
		PlaySFX(uiDiceRoll);
	}
}
